const body = $input.first().json.body || $input.first().json;

// Enforce boundary isolation: must have input (PharmacyReviewInput)
const input = body.input || body;

if (!input || !input.proposedPrescription || !input.patientId) {
  throw new Error('Invalid request payload: missing required PharmacyReviewInput boundary.');
}

const patientId = input.patientId;
const prescriptionDraft = input.proposedPrescription;
const relevantDiagnoses = input.relevantDiagnoses || [];
const allergies = input.allergies || [];
const currentMedications = input.currentMedications || [];
const relevantObservations = input.relevantObservations || [];
const deterministicFindings = input.deterministicFindings || [];
const unavailableData = input.unavailableData || [];

// System-owned metadata
const now = new Date();
const systemTimestamp = now.toISOString();
const systemId = body.id || `pr-review-${patientId}-${prescriptionDraft.id}-${now.getTime()}`;

// Extract supported availability gaps from input.unavailableData
const supportedGaps = unavailableData
  .filter(d => d && d.status && d.status !== 'AVAILABLE')
  .map(d => d.key);

const systemInstruction = `
Eres el Asistente Farmacéutico de SAMED (Sistema de Apoyo Médico para Evaluación y Decisión).
Tu rol es EXCLUSIVAMENTE CONSULTIVO Y DE REVISIÓN FARMACOTERAPÉUTICA para un prototipo con datos sintéticos.

INVARIANTES CRÍTICOS:
1. Los hallazgos determinísticos (deterministicFindings) son hallazgos determinísticos autoritativos dentro del prototipo SAMED. NUNCA los contradigas, descartes ni alteres.
2. La revisión que generas apoya la decisión del profesional; el médico retiene la AUTORIDAD DECISORIA FINAL.
3. NO autorizas ni emites recetas médicas.
4. Realizas una evaluación farmacológica independiente basada estrictamente en la medicación activa, alergias y pauta propuesta.
5. EVALUACIÓN DE ESTADO (status):
   - 'BLOCKED_BY_MISSING_DATA': Si faltan datos críticos respaldados en la entrada para evaluar la seguridad (ej. creatinina/eGFR en fármacos de eliminación renal, potasio en diuréticos/IECA). DATO FALTANTE ≠ NORMAL.
   - 'REVIEW_RECOMMENDED': Si hay hallazgos determinísticos activos de riesgo crítico o advertencia que requieren ajuste de dosis o consideración de alternativas.
   - 'NO_ADDITIONAL_CONCERNS': Si no se identifican contraindicaciones adicionales ni datos faltantes bloqueantes en el alcance analizado.
6. INVARIANTE SEMÁNTICO DE COLECCIONES VACÍAS: Un arreglo vacío en colecciones de entrada (como alergias: [], diagnósticos: [], medicamentos: [], observaciones: [], hallazgos: []) representa ausencia documentada de elementos, NO una brecha de datos. NUNCA reportes un arreglo vacío como brecha requerida.
7. Las brechas en requiredDataGaps deben ser ÚNICAMENTE brechas respaldadas explícitamente por los metadatos de indisponibilidad provistos en la entrada (datos no disponibles: ${JSON.stringify(supportedGaps)}). NUNCA inventes brechas de datos requeridos no respaldadas.
8. Genera tu salida ÚNICAMENTE en formato JSON conforme al esquema estricto especificado.
`;

const userPrompt = `
Por favor realiza la revisión farmacoterapéutica de la propuesta de prescripción para el paciente ${patientId}.

PROPUESTA DE PRESCRIPCIÓN:
ID: ${prescriptionDraft.id}
Ítems propuestos:
${JSON.stringify(prescriptionDraft.items || [], null, 2)}
Notas médicas:
${prescriptionDraft.notes || 'Sin notas'}

PERFIL FARMACOLÓGICO ACTIVO:
Diagnósticos relevantes: ${JSON.stringify(relevantDiagnoses)}
Alergias documentadas: ${JSON.stringify(allergies)}
Medicamentos en curso: ${JSON.stringify(currentMedications)}
Observaciones de monitoreo: ${JSON.stringify(relevantObservations)}

HALLAZGOS DETERMINÍSTICOS (Evidencia obligatoria):
${JSON.stringify(deterministicFindings, null, 2)}

DATOS ANALÍTICOS NO DISPONIBLES EN ENTRADA:
${JSON.stringify(unavailableData, null, 2)}

Genera la revisión en JSON con:
- status: 'NO_ADDITIONAL_CONCERNS' | 'REVIEW_RECOMMENDED' | 'BLOCKED_BY_MISSING_DATA'
- summary: síntesis narrativa de la revisión farmacológica
- pharmacologicalConsiderations: arreglo de cadenas con observaciones farmacológicas
- requiredDataGaps: arreglo de objetos { key: string, status: string, reason: string | null }
- deterministicFindingsReferenced: arreglo de cadenas con los IDs de los hallazgos determinísticos
- role: 'pharmacy_assistant'
`;

return [{
  json: {
    patientId,
    prescriptionDraftId: prescriptionDraft.id,
    systemId,
    systemTimestamp,
    systemInstruction,
    userPrompt,
    deterministicFindings,
    unavailableData,
    supportedGaps
  }
}];

const item = $input.first().json;
let prepData = {};
try {
  prepData = $('Validate & Prepare Prompt').first()?.json || {};
} catch (_) {}

if (item.error) {
  return [{
    json: {
      error: true,
      code: 'GROQ_API_ERROR',
      message: `Groq API Error: ${typeof item.error === 'object' ? JSON.stringify(item.error) : String(item.error)}`
    }
  }];
}

let parsed = null;

try {
  const rawContent = item.choices?.[0]?.message?.content;
  if (rawContent) {
    parsed = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
  } else if (item.status && item.summary) {
    parsed = item;
  } else {
    throw new Error('Groq API response did not contain valid message content or summary.');
  }
} catch (err) {
  return [{
    json: {
      error: true,
      code: 'MALFORMED_PROVIDER_OUTPUT',
      message: `Failed to parse Qwen provider response: ${err.message}`
    }
  }];
}

const validStatuses = ['NO_ADDITIONAL_CONCERNS', 'REVIEW_RECOMMENDED', 'BLOCKED_BY_MISSING_DATA'];
const validDataStatuses = ['AVAILABLE', 'MISSING', 'STALE', 'UNAVAILABLE', 'UNKNOWN'];

if (
  !parsed ||
  typeof parsed !== 'object' ||
  !validStatuses.includes(parsed.status) ||
  typeof parsed.summary !== 'string' ||
  !parsed.summary.trim() ||
  !Array.isArray(parsed.pharmacologicalConsiderations) ||
  !Array.isArray(parsed.requiredDataGaps) ||
  !Array.isArray(parsed.deterministicFindingsReferenced) ||
  parsed.role !== 'pharmacy_assistant'
) {
  return [{
    json: {
      error: true,
      code: 'INVALID_PHARMACY_REVIEW_STRUCTURE',
      message: 'Qwen provider output is missing required AI clinical fields or has invalid types/status/role.'
    }
  }];
}

const supportedGapsList = prepData.supportedGaps;
const supportedSet = Array.isArray(supportedGapsList) ? new Set(supportedGapsList) : null;

for (const gap of parsed.requiredDataGaps) {
  if (
    !gap ||
    typeof gap !== 'object' ||
    typeof gap.key !== 'string' ||
    !gap.key.trim() ||
    !validDataStatuses.includes(gap.status)
  ) {
    return [{
      json: {
        error: true,
        code: 'INVALID_PHARMACY_REVIEW_STRUCTURE',
        message: 'Qwen provider output contains invalid requiredDataGaps structure.'
      }
    }];
  }

  if (supportedSet && gap.status !== 'AVAILABLE' && !supportedSet.has(gap.key)) {
    return [{
      json: {
        error: true,
        code: 'INVALID_PHARMACY_REVIEW_STRUCTURE',
        message: `Qwen provider output contains unsupported or invented requiredDataGap: ${gap.key}`
      }
    }];
  }
}

if (!parsed.pharmacologicalConsiderations.every(item => typeof item === 'string')) {
  return [{
    json: {
      error: true,
      code: 'INVALID_PHARMACY_REVIEW_STRUCTURE',
      message: 'Qwen provider output contains non-string items in pharmacologicalConsiderations.'
    }
  }];
}

if (!parsed.deterministicFindingsReferenced.every(item => typeof item === 'string')) {
  return [{
    json: {
      error: true,
      code: 'INVALID_PHARMACY_REVIEW_STRUCTURE',
      message: 'Qwen provider output contains non-string items in deterministicFindingsReferenced.'
    }
  }];
}

const systemId = prepData.systemId || parsed.id || `pr-review-${prepData.patientId || parsed.patientId || 'pat-unknown'}-${prepData.prescriptionDraftId || parsed.prescriptionDraftId || 'draft-unknown'}-${Date.now()}`;
const systemPatientId = prepData.patientId || parsed.patientId || 'pat-unknown';
const systemDraftId = prepData.prescriptionDraftId || parsed.prescriptionDraftId || 'draft-unknown';
const systemTimestamp = prepData.systemTimestamp || parsed.reviewedAt || new Date().toISOString();

const normalized = {
  id: String(systemId),
  patientId: String(systemPatientId),
  prescriptionDraftId: String(systemDraftId),
  status: parsed.status,
  summary: String(parsed.summary),
  pharmacologicalConsiderations: parsed.pharmacologicalConsiderations.map(String),
  requiredDataGaps: parsed.requiredDataGaps.map(g => {
    const gapObj = { key: String(g.key), status: g.status };
    if (g.reason !== undefined && g.reason !== null && String(g.reason).trim() !== '') {
      gapObj.reason = String(g.reason);
    }
    return gapObj;
  }),
  deterministicFindingsReferenced: parsed.deterministicFindingsReferenced.map(String),
  reviewedAt: String(systemTimestamp),
  role: 'pharmacy_assistant'
};

return [{ json: normalized }];
